findings.codeql_raw_query:
/**
 * @name Untrusted data to file system paths
 * @description Detects flows from remote/user-controlled input into file system path operations (open, os.remove, shutil, etc.).
 * @kind path-problem
 * @problem.severity warning
 * @id py/virtualenv-remote-to-filesystem
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module RemoteToFsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module RemoteToFsFlow = TaintTracking::Global<RemoteToFsConfig>;
import RemoteToFsFlow::PathGraph

from RemoteToFsFlow::PathNode source, RemoteToFsFlow::PathNode sink
where RemoteToFsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data reaches a filesystem path in virtualenv: $@.", source.getNode(), "remote input"
